const $=s=>document.querySelector(s), money=n=>Number(n).toLocaleString('vi-VN')+' ₫', today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'}), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,5);
// Server data is cached only for rendering; all mutations use the API.
let db={foods:[],customers:[],suppliers:[],ingredients:[],combos:[],tables:[],bookings:[],imports:[],invoices:[]};
let session=null,page='reports',report='customers',from=today().slice(0,7)+'-01',to=today(),keyword='',category='Tất cả',selectedCustomer=null,cart=[],analytics=null,detailInvoices=[],searchResults=null;
const roles={manager:'Nhân viên quản lý',warehouse:'Nhân viên kho',sales:'Nhân viên bán hàng',customer:'Khách hàng'};const navs={manager:[['reports','▦','Báo cáo & thống kê'],['menu','♧','Quản lý món ăn'],['combos','◫','Menu combo']],warehouse:[['inventory','▤','Kho nguyên liệu'],['suppliers','♙','Nhà cung cấp']],sales:[['tables','▦','Sơ đồ bàn'],['bookings','▧','Đặt bàn trực tuyến'],['members','♙','Khách hàng & thẻ']],customer:[['menu','♧','Khám phá thực đơn'],['reserve','▧','Đặt bàn & đặt món'],['mybookings','◷','Lịch sử đặt bàn']]};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}function initials(s){return s.split(' ').slice(-2).map(x=>x[0]).join('')}function modal(title,body){$('#modal').innerHTML=`<div class="modalhead"><h2>${esc(title)}</h2><button class="close" aria-label="Đóng" onclick="closeModal()">×</button></div><div class="modalbody">${body}</div>`;$('#modal').showModal()}function closeModal(){$('#modal').close()}function val(id){return document.getElementById(id).value}function options(arr,id=''){return arr.map(x=>`<option value="${esc(x.id)}" ${id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}function render(){if(!session){$('#app').innerHTML=loginView();return}if(!navs[session.role].some(n=>n[0]===page))page=navs[session.role][0][0];let title=navs[session.role].find(n=>n[0]===page)[2];$('#app').innerHTML=`<aside><div class="brand"><span class="logo">♧</span><div>RestMan<small>RESTAURANT MANAGEMENT</small></div></div><div class="navlabel">KHÔNG GIAN LÀM VIỆC</div><nav>${navs[session.role].map(([p,i,n])=>`<button class="nav ${page===p?'active':''}" onclick="go('${p}')"><span class="ico">${i}</span>${n}</button>`).join('')}</nav><div class="sidebottom"><b>Nhà hàng The Garden</b><span class="dot"></span>Đang mở cửa · 09:00 – 22:00<br><span class="muted">Backend · SQLite</span></div></aside><main><header><div class="breadcrumb">Không gian làm việc &nbsp; / &nbsp; <b>${title}</b></div><div class="user"><div class="avatar">${esc(initials(session.name))}</div><div><strong>${esc(session.name)}</strong><small>${roles[session.role]}</small></div><button class="logout" title="Tải lại dữ liệu" onclick="reloadView()">⟳</button><button class="logout" title="Đổi mật khẩu" onclick="passwordForm()">⚿</button><button class="logout" title="Đăng xuất" onclick="logout()">↪</button></div></header><div class="content">${view()}</div><footer style="padding:0 36px 22px;display:flex;justify-content:space-between;color:#a0aa9b;font-size:9px"><span>© 2026 RestMan. Chăm chút từng trải nghiệm.</span><span>THE GARDEN RESTAURANT</span></footer></main>`}
function heading(t,s,action=''){return `<div class="heading"><div><h1>${t}</h1><p class="sub">${s}</p></div>${action||`<div class="datebadge">◷ &nbsp; ${new Date().toLocaleDateString('vi-VN',{timeZone:'Asia/Bangkok',weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div>`}</div>`}function stat(label,value,desc,icon){return `<div class="stat"><span>${label}</span><div class="sicon">${icon}</div><strong>${value}</strong><small>${desc}</small></div>`}function view(){switch(page){case'reports':return reportsView();case'menu':return menuView();case'combos':return combosView();case'inventory':return inventoryView();case'suppliers':return suppliersView();case'tables':return tablesView();case'bookings':return bookingsView(false);case'mybookings':return bookingsView(true);case'members':return membersView();case'reserve':return reserveView()}}
function filteredInvoices(){return db.invoices.filter(i=>i.date>=from&&i.date<=to)}function reportsView(){if(selectedCustomer)return customerDetail();let inv=filteredInvoices(),rows=reportRows(),total=analytics?.summary.total||0;return heading('Báo cáo & thống kê','Hiểu rõ hoạt động, đưa ra quyết định tốt hơn.',`<button class="secondary" onclick="exportReport()">⇩ &nbsp; Xuất báo cáo</button>`)+`<div class="stats">${stat('Tổng doanh thu',money(total),'<em>●</em> Trong khoảng thời gian đã chọn','₫')}${stat('Khách hàng phục vụ',rows.length+' khách','Khách hàng có hóa đơn thanh toán','♙')}${stat('Hóa đơn hoàn thành',inv.length+' hóa đơn','Đã thanh toán thành công','▤')}${stat('Giá trị hóa đơn TB',money(inv.length?Math.round(total/inv.length):0),'Tổng doanh thu / số hóa đơn','↗')}</div><section class="panel"><div class="tabs">${[['customers','Khách hàng theo doanh thu'],['foods','Món ăn'],['ingredients','Nguyên liệu'],['suppliers','Nhà cung cấp']].map(([k,v])=>`<button class="tab ${report===k?'active':''}" onclick="report='${k}';keyword='';render()">${v}</button>`).join('')}</div><form class="filters" onsubmit="event.preventDefault();applyDates()"><label>Từ ngày<input type="date" id="from" value="${from}" required></label><label>Đến ngày<input type="date" id="to" value="${to}" required></label><button class="primary">Áp dụng &nbsp; →</button><input class="search" aria-label="Tìm trong báo cáo" placeholder="⌕  Tìm tên hoặc số điện thoại..." value="${esc(keyword)}" oninput="keyword=this.value;updateReportTable()"></form><div id="report-table">${reportTable()}</div></section>${report==='customers'?`<div class="grid2"><section class="panel"><div class="panelhead"><div><h2>Doanh thu theo ngày</h2><p>Các ngày phát sinh doanh thu trong kỳ thống kê</p></div><span class="badge">● Doanh thu</span></div>${revenueChart(inv)}</section><section class="panel"><div class="panelhead"><div><h2>Khách hàng nổi bật</h2><p>Top 3 khách hàng theo doanh thu</p></div><span class="muted">↗</span></div><div class="ranking">${rows.slice(0,3).map((c,i)=>`<div class="rank"><span>${i+1}. ${esc(c.name)}</span><div class="progress"><i style="width:${rows[0]?.total?c.total/rows[0].total*100:0}%"></i></div><b>${money(c.total)}</b></div>`).join('')||'<p class="empty">Chưa có dữ liệu</p>'}</div></section></div>`:''}`}
function updateReportTable(){$('#report-table').innerHTML=reportTable()}function matches(s){return s.toLocaleLowerCase('vi').includes(keyword.toLocaleLowerCase('vi'))}function table(headers,body,empty='Không có dữ liệu phù hợp.'){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`}
function revenueChart(inv){let days=[...new Set(inv.map(i=>i.date))].sort(),amounts=days.map(d=>inv.filter(i=>i.date===d).reduce((s,i)=>s+i.total,0)),max=Math.max(...amounts,1);return `<div class="chart">${days.slice(-14).map((d,i)=>`<div class="bar" style="height:${amounts[i]/max*100}%" title="${d}: ${money(amounts[i])}"><span>${d.slice(8)}/${d.slice(5,7)}</span></div>`).join('')||'<p class="empty">Chưa có hóa đơn trong khoảng thời gian này.</p>'}</div>`}
function customerDetail(){let c=db.customers.find(c=>c.id===selectedCustomer),invoices=detailInvoices;return `<button class="back" onclick="selectedCustomer=null;render()">← Quay lại thống kê khách hàng</button>`+heading(esc(c.name),'Chi tiết các lần gọi món và hóa đơn thanh toán.')+`<div class="stats">${stat('Tổng chi tiêu',money(invoices.reduce((s,i)=>s+i.total,0)),'Trong kỳ thống kê','₫')}${stat('Lần gọi món',invoices.length,'Đã thanh toán','▤')}${stat('Hạng thành viên',esc(c.tier),'Số điện thoại: '+esc(c.phone),'♙')}</div><section class="panel"><div class="panelhead"><h2>Lịch sử gọi món · ${from} → ${to}</h2></div>${table(['Mã hóa đơn','Ngày gọi','Bàn','Tổng tiền','Thanh toán',''],invoices.map(i=>`<tr><td>${i.id}</td><td>${i.date.split('-').reverse().join('/')}</td><td>Bàn ${i.table}</td><td class="money">${money(i.total)}</td><td><span class="badge">Đã thanh toán</span></td><td><button class="link" onclick="invoice('${i.id}')">Xem hóa đơn →</button></td></tr>`).join(''))}</section>`}
function invoiceView(id){let i=db.invoices.find(i=>i.id===id),c=db.customers.find(c=>c.id===i.customer);modal('Hóa đơn '+i.id,`<div style="text-align:center"><h2>THE GARDEN RESTAURANT</h2><p class="muted">${i.date} · Bàn ${i.table}</p></div><p>Khách hàng: <b>${esc(c?.name||'Khách vãng lai')}</b><br>Phương thức: ${esc(i.method)}</p>${table(['Món ăn','SL','Thành tiền'],i.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td>${money(x.price*x.qty)}</td></tr>`).join(''))}<div class="receiptrow"><b>TỔNG THANH TOÁN</b><b class="invoiceTotal">${money(i.total)}</b></div><p style="text-align:center"><span class="badge">✓ Đã thanh toán</span></p><p class="sub" style="text-align:center">Cảm ơn quý khách. Hẹn gặp lại!</p>`)}
function menuView(){let manager=session.role==='manager';return heading(manager?'Quản lý món ăn':'Một chút ngon, một chút thương.',manager?'Chăm chút thực đơn, tạo nên trải nghiệm đáng nhớ.':'Khám phá những món ăn được chuẩn bị từ nguyên liệu tươi ngon.',manager?'<button class="primary" onclick="foodForm()">＋ Thêm món ăn</button>':'')+`<div class="toolbar"><input aria-label="Tìm tên món ăn" placeholder="⌕  Nhập tên món ăn để tìm kiếm..." value="${esc(keyword)}" oninput="keyword=this.value;updateFoods()"><select aria-label="Danh mục" onchange="category=this.value;updateFoods()">${['Tất cả','Khai vị','Món chính','Đồ uống','Tráng miệng'].map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="cards" id="foods">${foodCards()}</div>${!manager?`<section class="panel" style="margin-top:25px"><div class="panelhead"><h2>Combo cho những bữa ăn trọn vẹn</h2></div><div class="ranking">${db.combos.map(c=>`<div class="receiptrow"><div><b>${esc(c.name)}</b><p class="sub">${c.foods.map(id=>esc(db.foods.find(f=>f.id===id)?.name||'')).join(' · ')}</p></div><div><b class="money">${money(c.price)}</b> <button class="link" onclick="addCart('${c.id}',true)">Thêm ＋</button></div></div>`).join('')}</div></section>`:''}`}
function foodCards(){return (searchResults||db.foods).filter(f=>matches(f.name)&&(category==='Tất cả'||f.category===category)&&(session.role==='manager'||f.available)).map(f=>`<article class="food"><div class="foodpic" style="background:${({ 'Khai vị':'#edf1e5','Món chính':'#f3ede0','Đồ uống':'#e9f1e9'})[f.category]||'#f1e9e6'}">${f.icon}</div><div class="foodinfo"><span class="topnote">${esc(f.category.toUpperCase())} ${!f.available?'· TẠM HẾT':''}</span><h2 style="margin-top:10px">${esc(f.name)}</h2><p>${esc(f.desc)}</p><div class="foodrow"><strong class="money">${money(f.price)}</strong><button class="secondary small" onclick="foodDetail('${f.id}')">Xem chi tiết ↗</button>${session.role==='manager'?`<button class="link" onclick="foodForm('${f.id}')">Sửa</button>`:`<button class="primary small" onclick="addCart('${f.id}')">＋</button>`}</div></div></article>`).join('')||'<p class="empty">Không tìm thấy món ăn. Thử tên khác nhé.</p>'}function showFoodDetail(id){let f=db.foods.find(f=>f.id===id);modal(f.name,`<div class="foodpic" style="border-radius:10px">${f.icon}</div><p><span class="badge">${esc(f.category)}</span></p><p>${esc(f.desc)}</p><p><b>Nguyên liệu:</b> ${esc(f.ingredients)}</p><p><b>Giá:</b> <span class="invoiceTotal">${money(f.price)}</span></p><p class="sub">Vui lòng báo cho nhân viên nếu bạn dị ứng với bất kỳ nguyên liệu nào.</p>${session.role==='customer'?`<div class="actions"><button class="primary" onclick="addCart('${id}');closeModal()">Thêm vào món đặt trước ＋</button></div>`:''}`)}
function foodForm(id){let f=db.foods.find(f=>f.id===id)||{name:'',category:'Món chính',price:'',desc:'',ingredients:'',icon:'🍽️',available:true};modal(id?'Chỉnh sửa món ăn':'Thêm món ăn',`<form onsubmit="event.preventDefault();saveFood('${id||''}')"><div class="formgrid"><label class="full">Tên món<input id="fname" required maxlength="100" value="${esc(f.name)}"></label><label>Danh mục<select id="fcat">${['Khai vị','Món chính','Đồ uống','Tráng miệng'].map(c=>`<option ${c===f.category?'selected':''}>${c}</option>`).join('')}</select></label><label>Giá bán (₫)<input type="number" id="fprice" required min="1000" step="1000" value="${f.price}"></label><label class="full">Mô tả<textarea id="fdesc" required>${esc(f.desc)}</textarea></label><label class="full">Nguyên liệu<input id="fingredients" required value="${esc(f.ingredients)}"></label><label>Biểu tượng món<input id="ficon" required maxlength="8" value="${esc(f.icon)}"></label><label>Trạng thái<select id="favailable"><option value="true" ${f.available?'selected':''}>Đang phục vụ</option><option value="false" ${!f.available?'selected':''}>Tạm hết</option></select></label></div><div class="actions"><button type="button" class="secondary" onclick="closeModal()">Hủy</button><button class="primary">Lưu món ăn</button></div></form>`)}function combosView(){return heading('Menu combo','Kết hợp món ngon, tạo thêm lựa chọn cho khách hàng.','<button class="primary" onclick="comboForm()">＋ Tạo combo</button>')+`<div class="cards">${db.combos.map(c=>`<article class="food"><div class="foodpic">🍱</div><div class="foodinfo"><span class="topnote">THỰC ĐƠN KẾT HỢP</span><h2 style="margin-top:12px">${esc(c.name)}</h2><p>${c.foods.map(id=>esc(db.foods.find(f=>f.id===id)?.name||'')).join('<br>')}</p><div class="foodrow"><b class="money">${money(c.price)}</b><button class="secondary small" onclick="comboForm('${c.id}')">Chỉnh sửa</button><button class="link" onclick="deleteCombo('${c.id}')">Xóa</button></div></div></article>`).join('')||'<p class="empty">Tạo combo đầu tiên của nhà hàng.</p>'}</div>`}function comboForm(id){let c=db.combos.find(c=>c.id===id)||{name:'',price:'',foods:[]};modal('Thiết lập combo',`<form onsubmit="event.preventDefault();saveCombo('${id||''}')"><div class="formgrid"><label class="full">Tên combo<input id="coname" required value="${esc(c.name)}"></label><label class="full">Giá combo (₫)<input id="coprice" type="number" required min="1000" step="1000" value="${c.price}"></label><div class="full"><p>Chọn tối thiểu 2 món:</p>${db.foods.map(f=>`<label style="display:flex;align-items:center;margin:12px 0"><input type="checkbox" name="combofood" value="${f.id}" ${c.foods.includes(f.id)?'checked':''}>${esc(f.name)} · ${money(f.price)}</label>`).join('')}</div></div><div class="actions"><button class="primary">Lưu combo</button></div></form>`)}function inventoryView(){return heading('Kho nguyên liệu','Theo dõi tồn kho và nhập nguyên liệu từ nhà cung cấp.','<button class="primary" onclick="importForm()">＋ Nhập nguyên liệu</button>')+`<div class="stats">${stat('Loại nguyên liệu',db.ingredients.length,'Đang theo dõi trong kho','▤')}${stat('Cần bổ sung',db.ingredients.filter(i=>i.stock<i.min).length,'Dưới ngưỡng tồn tối thiểu','!')}${stat('Phiếu nhập',db.imports.length,'Tổng số lần nhập nguyên liệu','↙')}${stat('Tổng giá trị nhập',money(db.imports.reduce((s,i)=>s+i.qty*i.price,0)),'Dữ liệu nhập kho đã ghi nhận','₫')}</div><section class="panel"><div class="panelhead"><h2>Tồn kho hiện tại</h2><button class="secondary small" onclick="ingredientForm()">＋ Loại nguyên liệu</button></div>${table(['Nguyên liệu','Đơn vị','Tồn kho','Tồn tối thiểu','Trạng thái'],db.ingredients.map(i=>`<tr><td><b>${esc(i.name)}</b></td><td>${esc(i.unit)}</td><td>${i.stock}</td><td>${i.min}</td><td><span class="badge ${i.stock<i.min?'orange':''}">${i.stock<i.min?'Cần nhập thêm':'Đủ tồn kho'}</span></td></tr>`).join(''))}</section><section class="panel"><div class="panelhead"><h2>Lịch sử nhập kho</h2></div>${table(['Ngày nhập','Nhà cung cấp','Nguyên liệu','Số lượng','Đơn giá','Thành tiền'],[...db.imports].reverse().map(i=>`<tr><td>${i.date}</td><td>${esc(db.suppliers.find(s=>s.id===i.supplier)?.name)}</td><td>${esc(db.ingredients.find(s=>s.id===i.ingredient)?.name)}</td><td>${i.qty}</td><td>${money(i.price)}</td><td class="money">${money(i.price*i.qty)}</td></tr>`).join(''))}</section>`}
function ingredientForm(){modal('Thêm loại nguyên liệu',`<form onsubmit="event.preventDefault();addIngredient()"><div class="formgrid"><label class="full">Tên nguyên liệu<input id="iname" required></label><label>Đơn vị<input id="iunit" required placeholder="kg, lít, ..."></label><label>Tồn tối thiểu<input id="imin" type="number" min="0" step="0.1" required value="5"></label></div><div class="actions"><button class="primary">Thêm nguyên liệu</button></div></form>`)}function importForm(){modal('Nhập nguyên liệu',`<form onsubmit="event.preventDefault();saveImport()"><div class="formgrid"><label class="full">Nhà cung cấp<select id="isupplier" required>${options(db.suppliers)}</select></label><label class="full">Nguyên liệu<select id="iingredient" required>${options(db.ingredients.map(i=>({...i,name:i.name+' ('+i.unit+')'})))}</select></label><label>Số lượng<input id="iqty" type="number" min="0.1" step="0.1" required></label><label>Đơn giá / đơn vị (₫)<input id="iprice" type="number" min="1" required></label><label class="full">Ngày nhập<input id="idate" type="date" required value="${today()}" max="${today()}"></label></div><div class="actions"><button class="primary">Xác nhận nhập kho</button></div></form>`)}function suppliersView(){return heading('Nhà cung cấp','Quản lý các đối tác cung ứng nguyên liệu cho nhà hàng.','<button class="primary" onclick="supplierForm()">＋ Thêm nhà cung cấp</button>')+`<section class="panel">${table(['Nhà cung cấp','Điện thoại','Địa chỉ',''],db.suppliers.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.phone)}</td><td>${esc(s.address)}</td><td><button class="link" onclick="supplierForm('${s.id}')">Chỉnh sửa →</button></td></tr>`).join(''))}</section>`}function supplierForm(id){let s=db.suppliers.find(s=>s.id===id)||{name:'',phone:'',address:''};modal(id?'Chỉnh sửa nhà cung cấp':'Thêm nhà cung cấp',`<form onsubmit="event.preventDefault();saveSupplier('${id||''}')"><div class="formgrid"><label class="full">Tên nhà cung cấp<input id="sname" required value="${esc(s.name)}"></label><label class="full">Điện thoại<input id="sphone" required pattern="[0-9+ .-]{9,15}" value="${esc(s.phone)}"></label><label class="full">Địa chỉ<input id="saddress" required value="${esc(s.address)}"></label></div><div class="actions"><button class="primary">Lưu thông tin</button></div></form>`)}function tablesView(){return heading('Sơ đồ bàn','Nhận khách, gọi món và thanh toán ngay tại bàn.')+`<div class="stats">${stat('Tổng số bàn',db.tables.length,'Sẵn sàng phục vụ','▦')}${stat('Bàn đang dùng',db.tables.filter(t=>t.customer).length,'Khách đang dùng bữa','♙')}${stat('Bàn còn trống',db.tables.filter(t=>!t.customer).length,'Có thể nhận khách','◫')}${stat('Chờ xác nhận',db.bookings.filter(b=>b.status==='Chờ xác nhận').length,'Đặt bàn trực tuyến','◷')}</div><div class="notice">Chọn một bàn để nhận khách hoặc cập nhật món ăn. &nbsp; ● Xanh: bàn trống &nbsp; ● Vàng: đang phục vụ</div><div class="tables">${db.tables.map(t=>`<button class="dining ${t.customer?'busy':''}" onclick="tableDetail(${t.id})"><span class="ico">♧</span><strong>Bàn ${String(t.id).padStart(2,'0')}</strong><small>${t.seats} chỗ ngồi · ${t.customer?'Đang phục vụ':'Còn trống'}</small>${t.customer?`<p class="money">${money(t.items.reduce((s,x)=>s+x.price*x.qty,0))}</p>`:''}</button>`).join('')}</div>`}
function tableDetail(id){let t=db.tables.find(t=>t.id===id);if(!t.customer){modal('Nhận khách · Bàn '+id,`<form onsubmit="event.preventDefault();receiveGuest(${id})"><label>Khách hàng<select id="tcustomer"><option value="walkin">Khách vãng lai</option>${options(db.customers)}</select></label><p class="sub" style="margin-top:15px">Bàn ${id} · Tối đa ${t.seats} khách.</p><div class="actions"><button class="primary">Nhận khách</button></div></form>`);return}modal('Phục vụ · Bàn '+id,`<p>Khách hàng: <b>${esc(db.customers.find(c=>c.id===t.customer)?.name||'Khách vãng lai')}</b></p>${table(['Món đã gọi','Số lượng','Thành tiền',''],t.items.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td>${money(x.price*x.qty)}</td><td><button class="link" onclick="removeItem(${id},${i})">Bỏ</button></td></tr>`).join(''))}<form onsubmit="event.preventDefault();addTableItem(${id})" class="formgrid" style="margin-top:20px"><label>Món ăn<select id="tfood">${options(db.foods.filter(f=>f.available))}${options(db.combos.map(c=>({...c,name:'Combo: '+c.name})))}</select></label><label>Số lượng<input id="tqty" type="number" min="1" max="99" value="1" required></label><button class="secondary full">＋ Thêm món vào bàn</button></form><div class="receiptrow"><b>Tạm tính</b><b class="money">${money(t.items.reduce((s,x)=>s+x.qty*x.price,0))}</b></div><div class="actions">${!t.items.length?`<button class="secondary" onclick="releaseTable(${id})">Trả bàn trống</button>`:''}<button class="primary" ${!t.items.length?'disabled':''} onclick="paymentForm(${id})">Thanh toán tại bàn →</button></div>`)}
function paymentForm(id){let t=db.tables.find(t=>t.id===id);modal('Thanh toán · Bàn '+id,`<p>Tổng tiền cần thanh toán</p><p class="invoiceTotal">${money(t.items.reduce((s,x)=>s+x.qty*x.price,0))}</p><label>Phương thức thanh toán<select id="pmethod"><option>Tiền mặt</option><option>Chuyển khoản</option><option>Thẻ ngân hàng</option></select></label><p class="sub" style="margin-top:15px">Chỉ xác nhận sau khi đã nhận đủ tiền từ khách hàng.</p><div class="actions"><button class="secondary" onclick="closeModal();tableDetail(${id})">Quay lại</button><button class="primary" onclick="pay(${id})">Xác nhận đã nhận tiền</button></div>`)}function membersView(){return heading('Khách hàng & thẻ thành viên','Ghi nhận khách hàng và đồng hành cùng mỗi lần ghé thăm.','<button class="primary" onclick="memberForm()">＋ Làm thẻ thành viên</button>')+`<section class="panel">${table(['Khách hàng','Số điện thoại','Hạng thẻ','Mã thẻ',''],db.customers.map(c=>`<tr><td><div class="person"><span class="avatar">${initials(c.name)}</span><b>${esc(c.name)}</b></div></td><td>${esc(c.phone)}</td><td><span class="badge ${c.tier==='Vàng'?'gold':''}">${c.tier}</span></td><td>RM-${esc(c.id.toUpperCase())}</td><td><button class="link" onclick="memberCard('${c.id}')">Xem thẻ →</button></td></tr>`).join(''))}</section>`}function memberForm(){modal('Làm thẻ thành viên',`<form onsubmit="event.preventDefault();saveMember()"><div class="formgrid"><label class="full">Họ tên khách hàng<input id="mname" required maxlength="80"></label><label class="full">Số điện thoại<input id="mphone" required pattern="0[0-9]{9}" placeholder="10 chữ số, bắt đầu bằng 0"></label></div><div class="actions"><button class="primary">Tạo thẻ thành viên</button></div></form>`)}function memberCard(id){let c=db.customers.find(c=>c.id===id);modal('Thẻ thành viên RestMan',`<div style="background:#174e39;color:white;border-radius:13px;padding:30px"><div class="brand" style="color:white">RestMan</div><p style="color:#a9c4a4;font-size:10px;letter-spacing:3px">THE GARDEN · MEMBERSHIP</p><h2 style="margin:35px 0 12px;font-size:23px">${esc(c.name)}</h2><p>${esc(c.phone)}<br>RM-${esc(c.id.toUpperCase())}</p><span class="badge gold">${c.tier}</span></div>`)}
function addCart(id,combo=false){let f=(combo?db.combos:db.foods).find(f=>f.id===id),item=cart.find(x=>x.id===id);if(item)item.qty++;else cart.push({id,name:f.name,price:f.price,qty:1});toast('Đã thêm '+f.name+' vào món đặt trước.');if(page==='reserve')render()}function reserveView(){return heading('Hẹn một bữa ăn ngon.','Chọn bàn, đặt món trước và để chúng tôi chuẩn bị cho bạn.')+`<div class="grid2"><section class="panel"><div class="panelhead"><h2>Thông tin đặt bàn</h2><span class="badge">ĐẶT TRỰC TUYẾN</span></div><form style="padding:0 23px 23px" onsubmit="event.preventDefault();submitBooking()"><div class="formgrid"><label>Họ và tên<input id="bname" required maxlength="80" value="${esc(session.name)}"></label><label>Điện thoại<input id="bphone" value="${esc(db.customers.find(c=>c.id===session.customer)?.phone||'')}" required pattern="0[0-9]{9}" placeholder="VD: 0901234567"></label><label>Ngày đến<input id="bdate" type="date" min="${today()}" value="${today()}" required></label><label>Giờ đến<input id="btime" type="time" min="09:00" max="21:00" value="18:30" required></label><label>Số khách<input id="bguests" type="number" min="1" max="6" value="2" required></label><label>Bàn mong muốn<select id="btable">${db.tables.map(t=>`<option value="${t.id}">Bàn ${t.id} · ${t.seats} chỗ</option>`).join('')}</select></label><label class="full">Ghi chú<textarea id="bnote" placeholder="Dị ứng, dịp đặc biệt hoặc yêu cầu khác..."></textarea></label></div><p class="sub" style="margin-top:15px">Đặt bàn cần được nhân viên xác nhận. Món ăn đặt trước sẽ được thanh toán tại nhà hàng.</p><div class="actions"><button class="primary">Gửi yêu cầu đặt bàn →</button></div></form></section><section class="panel"><div class="panelhead"><h2>Món đặt trước (${cart.reduce((s,x)=>s+x.qty,0)})</h2><button class="link" onclick="go('menu')">＋ Chọn món</button></div><div class="ranking">${cart.map((x,i)=>`<div class="receiptrow"><div><b>${esc(x.name)}</b><p class="sub">${money(x.price)} × ${x.qty}</p></div><div><b>${money(x.price*x.qty)}</b><br><button class="link" onclick="cart.splice(${i},1);render()">Bỏ món</button></div></div>`).join('')||'<p class="empty">Chưa có món đặt trước.<br>Bạn có thể gọi món khi đến nhà hàng.</p>'}<div class="receiptrow"><b>Tạm tính</b><b class="money">${money(cart.reduce((s,x)=>s+x.qty*x.price,0))}</b></div></div></section></div>`}function bookingsView(mine){let rows=mine?db.bookings.filter(b=>b.userId===session.id):db.bookings;return heading(mine?'Lịch sử đặt bàn':'Đặt bàn trực tuyến',mine?'Theo dõi trạng thái các yêu cầu đặt bàn và đặt món của bạn.':'Xác nhận thông tin và chuẩn bị chu đáo cho khách hàng.')+`<section class="panel"><div class="panelhead"><h2>${mine?'Yêu cầu của bạn':'Danh sách đặt bàn'}</h2><span class="badge">${rows.length} yêu cầu</span></div>${table(['Khách hàng','Thời gian','Bàn / Khách','Món đặt trước','Trạng thái',''],[...rows].reverse().map(b=>`<tr><td><strong>${esc(b.name)}</strong><small>${esc(b.phone)}</small></td><td>${b.date}<small>${b.time}</small></td><td>Bàn ${b.table} · ${b.guests} khách</td><td>${b.items.reduce((s,x)=>s+x.qty,0)} món</td><td><span class="badge ${b.status==='Chờ xác nhận'?'orange':''}">${b.status}</span></td><td><button class="link" onclick="bookingDetail('${b.id}')">Chi tiết →</button></td></tr>`).join(''))}</section>`}function bookingDetail(id){let b=db.bookings.find(b=>b.id===id);modal('Chi tiết đặt bàn',`<p><b>${esc(b.name)}</b> · ${esc(b.phone)}<br>${b.date} lúc ${b.time}<br>Bàn ${b.table} · ${b.guests} khách</p><p>Ghi chú: ${esc(b.note||'Không có')}</p>${table(['Món đặt trước','SL','Thành tiền'],b.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td>${money(x.price*x.qty)}</td></tr>`).join(''))}<div class="receiptrow"><b>Trạng thái</b><span class="badge">${b.status}</span></div><div class="actions">${['Chờ xác nhận','Đã xác nhận'].includes(b.status)?`<button class="secondary" onclick="bookingStatus('${id}','Đã hủy')">Hủy đặt bàn</button>`:''}${session.role==='sales'&&b.status==='Chờ xác nhận'?`<button class="primary" onclick="bookingStatus('${id}','Đã xác nhận')">Xác nhận thông tin</button>`:''}${session.role==='sales'&&b.status==='Đã xác nhận'?`<button class="primary" onclick="checkIn('${id}')">Nhận khách vào bàn</button>`:''}</div>`)}